STORE_DATA_SHEET_ID = "1eNpYmFkubjtFEwKgnpzFp2DUGoMBYJklDCy1gGOa5Rw"
STORE_DATA_TAB = "店舗データ"
STORE_AM_NAMES = {"渡邊_A", "渡邊_B"}

def load_master():
    """店舗データから渡邊_A/BかつOPENの店舗を取得する。"""
    try:
        import gspread
        client = gspread.service_account_from_dict(dict(st.secrets["gcp_service_account"]))
        values = client.open_by_key(STORE_DATA_SHEET_ID).worksheet(STORE_DATA_TAB).get_all_values()
        stores = []
        for row in values[1:]:
            row = list(row) + [""] * max(0, 9 - len(row))
            am_name = str(row[4]).strip()
            open_status = str(row[7]).strip().upper()
            if am_name not in STORE_AM_NAMES or open_status != "OPEN":
                continue
            stores.append({
                "店舗コード": str(row[0]).strip(),
                "店舗ID": str(row[1]).strip(),
                "店舗名": str(row[2]).strip(),
                "代行会社": str(row[6]).strip(),
                "エリア": str(row[8]).strip(),
                "AM名": am_name,
            })
        if stores:
            return stores
    except Exception as exc:
        st.session_state["_store_master_error"] = str(exc)

    # Google Sheetsへ接続できない場合は現在保存済みの一覧を維持
    return load_saved_master()

def load_saved_master():
    """Google Sheetsへアクセスせず、現在保存済みの店舗一覧を読み込む。"""
    if os.path.exists(MASTER_FILE):
        with open(MASTER_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        for d in data:
            if "AMName" in d and "AM名" not in d:
                d["AM名"] = d.pop("AMName")
        return data
    return [dict(d) for d in DEFAULT_STORES]

def save_master(stores):
    with open(MASTER_FILE, "w", encoding="utf-8") as f:
        json.dump(stores, f, ensure_ascii=False, indent=2)

TARGET_FILE = "targets.json"

def load_targets():
    import datetime
    if os.path.exists(TARGET_FILE):
        with open(TARGET_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        # 月次自動リセット：保存時の年月と現在の年月が違えば削除
        saved_ym = data.get("_saved_ym", "")
        current_ym = _jst_today().strftime("%Y%m")
        if saved_ym and saved_ym != current_ym:
            os.remove(TARGET_FILE)
            return {}
        return {k: v for k, v in data.items() if k != "_saved_ym"}
    return {}

def save_targets(targets):
    with open(TARGET_FILE, "w", encoding="utf-8") as f:
        json.dump(targets, f, ensure_ascii=False, indent=2)

def load_targets_from_csv(sales_file, target_sales_file, target_zasu_file, master_df):
    """
    目標CSVから日別目標をマスタ店舗IDで紐付けて返す。
    目標CSVのE列店舗名はシステム名と異なる場合があるため、
    K列(店舗ID数字)とマスタの店舗IDで紐付ける。
    """
    import datetime as _dt_tgt

    # マスタから 店舗ID → 店舗名 のマッピングを作成
    id_to_name = {}
    for _, row in master_df.iterrows():
        sid = str(row.get('店舗ID', '') or '').strip()
        sname = str(row.get('店舗名', '') or '').strip()
        if sid and sname and sid != 'nan':
            id_to_name[sid] = sname

    targets = {}
    metric_map = {
        "受注金額(税抜)": target_sales_file,
        "座数":          target_zasu_file,
    }

    for metric, tfile in metric_map.items():
        if tfile is None:
            continue
        tfile.seek(0)
        tdf = pd.read_csv(tfile, encoding="utf-8", header=None)

        # E列=4(店舗名), F列=5(日付), M列=12(目標値)
        if tdf.shape[1] <= 12:
            continue
        tdf = tdf[[4, 5, 12]].copy()
        tdf.columns = ["店舗名", "日付", "目標値"]
        tdf = tdf.dropna(subset=["店舗名", "日付", "目標値"])

        # ヘッダー・集計行を除外（店舗名が実店舗名でない行）
        exclude = ["受注目標", "座数目標", "スマレジ店舗ID", "nan", "NaN", "店舗名"]
        tdf["店舗名"] = tdf["店舗名"].astype(str).str.strip()
        tdf = tdf[~tdf["店舗名"].isin(exclude)]
        tdf = tdf[tdf["店舗名"].str.len() > 1]

        # 目標値を数値化
        tdf["目標値"] = pd.to_numeric(
            tdf["目標値"].astype(str).str.replace(",", ""), errors="coerce"
        )
        tdf = tdf.dropna(subset=["目標値"])
        tdf = tdf[tdf["目標値"] > 0]

        # 日付を正規化: "2026/8/1" → "2026/08/01"
        def _norm_date(d):
            try:
                parts = str(d).strip().split('/')
                return f"{int(parts[0])}/{int(parts[1]):02d}/{int(parts[2]):02d}"
            except:
                return None
        tdf["日付"] = tdf["日付"].apply(_norm_date)
        tdf = tdf.dropna(subset=["日付"])

        # マスタに存在する店舗名のみに絞る（店舗名で直接照合）
        master_stores = set(master_df['店舗名'].dropna().astype(str).str.strip())
        tdf = tdf[tdf["店舗名"].isin(master_stores)]

        # 日別目標を保存: "店舗名_指標_YYYY/MM/DD" = 値
        for _, row in tdf.iterrows():
            date_key = f"{row['店舗名']}_{metric}_{row['日付']}"
            targets[date_key] = str(int(row["目標値"]))

        # 月間目標（日別の合計）も店舗ごとに保存
        store_totals = tdf.groupby("店舗名")["目標値"].sum()
        for sname, total in store_totals.items():
            targets[f"{sname}_{metric}"] = str(int(total))

    return targets

# ─────────────────────────────────────────────
# CSV ヘルパー
# ─────────────────────────────────────────────
def to_numeric_safe(series):
    return pd.to_numeric(
        series.astype(str).str.replace("%","",regex=False).str.replace(",","",regex=False),
        errors="coerce"
    )

@st.cache_data(show_spinner=False)
def load_csv_cached(file_bytes: bytes) -> pd.DataFrame:
    """バイト列からCSVを読み込み（キャッシュ対応）"""
    import io
    for enc in ("shift_jis", "utf-8", "cp932"):
        try:
            return pd.read_csv(io.BytesIO(file_bytes), encoding=enc)
        except Exception:
            continue
    raise ValueError("文字コードを判定できませんでした")

def load_csv(file):
    file.seek(0)
    return load_csv_cached(file.read())

def get_date_cols(df):
    return [c for c in df.columns if str(c)[:4].isdigit() and "/" in str(c)]

@st.cache_data(show_spinner=False)
def to_long_cached(sales_bytes: bytes, store_names_tuple: tuple, label: str, master_json_str: str) -> pd.DataFrame:
    """全期間のlong形式DataFrameをキャッシュ。期間絞込はこの後に行う。"""
    import json
    sales_df  = load_csv_cached(sales_bytes)
    master_df = pd.DataFrame(json.loads(master_json_str))
    return _to_long_impl(sales_df, list(store_names_tuple), label, master_df)

def to_long(sales_df, store_names, label, master_df):
    return _to_long_impl(sales_df, store_names, label, master_df)

def _to_long_impl(sales_df, store_names, label, master_df):
    date_cols = get_date_cols(sales_df)
    sales_df = sales_df.copy()
    # 店舗IDを整数に変換（文字列比較の誤りを防ぐ）
    def safe_int(x):
        try: return int(str(x).strip())
        except: return -1
    sales_df["店舗ID_int"] = sales_df["店舗ID"].apply(safe_int)
    rows = []
    for _, sr in master_df[master_df["店舗名"].isin(store_names)].iterrows():
        sname = sr["店舗名"]
        scode = str(sr.get("店舗コード","")).strip()
        sid_int = safe_int(sr.get("店舗ID", -1))

        # ① 店舗IDの整数値で突合（最優先・確実）
        if sid_int > 0:
            sub_store = sales_df[sales_df["店舗ID_int"] == sid_int]
        else:
            sub_store = pd.DataFrame()
        # ② IDがない場合は店舗コードで突合（複数IDは数値最大を選択）
        if sub_store.empty:
            sub_store = sales_df[sales_df["店舗コード"].astype(str).str.strip() == scode]
            if not sub_store.empty and sub_store["店舗ID_int"].nunique() > 1:
                max_int_id = sub_store["店舗ID_int"].max()
                sub_store = sub_store[sub_store["店舗ID_int"] == max_int_id]
        # ③ フォールバック：店舗名
        if sub_store.empty:
            sub_store = sales_df[sales_df["店舗名"] == sname]

        for metric in KEY_METRICS:
            sub = sub_store[sub_store["項目名"]==metric]
            if sub.empty:
                continue
            for dc in date_cols:
                val = to_numeric_safe(sub[dc]).values[0] if dc in sub.columns else None
                parts = str(dc).split("/")
                month_day = f"{int(parts[1]):02d}/{int(parts[2]):02d}" if len(parts)==3 else dc
                rows.append({
                    "店舗名": sname, "店舗コード": scode,
                    "代行会社": sr["代行会社"], "エリア": sr["エリア"],
                    "日付_原本": dc, "月日": month_day,
                    "年度": label, "指標": metric, "値": val,
                })
    return pd.DataFrame(rows)

